sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_SPEED;
uniform float amzp_progress;
uniform float amzp_xnxx;
uniform float amzp_alpha;
uniform float amzp_scaleuv;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_space;
uniform float amzp_scalex;
uniform float amzp_scaley;
uniform float amzp_scalez;
uniform float amzp_alpx;
uniform float amzp_alpy;
uniform float amzp_refr;
uniform float amzp_fog;
uniform float amzp_fogClear;
uniform float amzp_xxx;
uniform float amzp_lightfx;
uniform float amzp_aai;
uniform float amzp_quality;
    float2x2 rot2m(float a) { float s = sin(a), c = cos(a); return float2x2(c, -s, s, c); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float3 N13(float p) {
        float3 p3 = fract(float3(p) * float3(0.1031, 0.11369, 0.13787));
        p3 += dot(p3, p3.yzx + 19.19);
        return fract(float3((p3.x + p3.y) * p3.z, (p3.x + p3.z) * p3.y, (p3.y + p3.z) * p3.x));
    }
    float N(float t) { return fract(sin(t * 12345.564) * 7658.76); }
    float Saw(float b, float t) { return smoothstep(0.0, b, t) * smoothstep(1.0, b, t); }
    float2 DropLayer2(float2 uv, float t) {
        float2 UV = uv;
        uv.y += t * 0.75;
        float2 a = float2(amzp_space.x, 1.0);
        float2 grid = a * 2.0;
        float2 id = floor(uv * grid);
        uv.y += N(id.x);
        id = floor(uv * grid);
        float3 n = N13(id.x * 35.2 + id.y * 2376.1);
        float2 st = fract(uv * grid) - float2(0.5, 0.0);
        float x = n.x - 0.5;
        float y = UV.y * 20.0;
        float wiggle = sin(y + sin(y));
        x += wiggle * (0.5 - abs(x)) * (n.z - 0.5);
        x *= 0.7;
        float ti = fract(t + n.z);
        y = (Saw(0.85, ti) - 0.5) * 0.9 + 0.5;
        float2 p = float2(x, y);
        float d = length((st - p) * a.yx);
        float mainDrop = smoothstep(0.4, 0.0, d);
        float r = sqrt(smoothstep(1.0, y, st.y));
        float cd = abs(st.x - x);
        float trail = smoothstep(0.23 * r, 0.15 * r * r, cd);
        float trailFront = smoothstep(-0.02, 0.02, st.y - y);
        trail *= trailFront * r * r;
        y = fract(UV.y * amzp_space.y) + (st.y - 0.5);
        float droplets = smoothstep(0.3, 0.0, length(st - float2(x, y)));
        float m = (mainDrop + droplets * r * trailFront) * amzp_alpy;
        return float2(m, trail);
    }
    float StaticDrops(float2 uv, float t) {
        uv *= 40.0;
        float2 id = floor(uv);
        uv = fract(uv) - 0.5;
        float3 n = N13(id.x * 107.45 + id.y * 3543.654);
        float2 p = (n.xy - 0.5) * 0.7;
        float d = length(uv - p);
        float fade = Saw(0.025, fract(t + n.z));
        return smoothstep(0.3, 0.0, d) * fract(n.z * 10.0) * fade * amzp_alpx;
    }
    float3 Drops(float2 uv, float t, float l0, float l1, float l2) {
        float s = (l0 > 0.0 && amzp_alpx > 0.0) ? StaticDrops(uv * amzp_scalex, t) * l0 : 0.0;
        float2 m1 = (l1 > 0.0 && amzp_scaley != 0.0 && amzp_alpy > 0.0) ? DropLayer2(uv * amzp_scaley, t) * l1 : float2(0.0);
        float2 m2 = (l2 > 0.0 && amzp_scalez != 0.0 && amzp_alpy > 0.0) ? DropLayer2(uv * amzp_scalez, t) * l2 : float2(0.0);
        float raw = s + m1.x + m2.x;
        return float3(smoothstep(0.3, 1.0, raw), max(m1.y * l0, m2.y * l1), raw);
    }
    float4 tex(float2 u) { return amzTexture(0, u); }
    void amzRender() {
        float4 texColor = tex(amzScreenNorm());
        float2 sat = ((float2(amzScreenNorm().x, 1.0 - amzScreenNorm().y) * screen.zw) - amzLayerCenter()) / layer;
        sat.y *= layer.y / layer.x;
        sat /= (amzp_xnxx>0.5) ? (amzp_scaleuv + 1.5) : amzp_scaleuv;
        sat *= rot2m((-180.0 + amzp_angle) * 0.0174533);
        sat += amzp_position * float2(-1.0, 1.0) / 500.0;
        float2 uv = sat;
        float2 UV = amzScreenNorm();
        float iTime = (amzp_autop>0.5) ? amzp_progress + time * amzp_SPEED : amzp_progress;
        float T = iTime;
        if ((amzp_xnxx>0.5)) T = mod(iTime, 102.0);
        float t = T * 0.2;
        float rainAmount = sin(T * 0.05) * 0.3 + 0.7;
        float maxBlur = mix(3.0, 6.0, rainAmount);
        float minBlur = 2.0;
        float story = 0.0;
        float heart = 0.0;
        if ((amzp_xnxx>0.5)) {
            story = smoothstep(0.0, 70.0, T);
            t = min(1.0, T / 70.0);
            t = 1.0 - t;
            t = (1.0 - t * t) * 70.0;
            minBlur = 4.0 + smoothstep(0.5, 1.0, story) * 3.0;
            maxBlur = 6.0 + smoothstep(0.5, 1.0, story) * 1.5;
            float2 hv = uv - float2(0.0, -0.1);
            hv.x *= 0.5;
            float s = smoothstep(110.0, 70.0, T);
            hv.y -= sqrt(abs(hv.x)) * 0.5 * s;
            heart = smoothstep(0.4 * s, 0.2 * s, length(hv)) * s;
            rainAmount = heart;
            maxBlur -= heart;
            uv *= 1.5;
            t *= 0.25;
        }
        float staticDrops = smoothstep(-0.5, 1.0, rainAmount) * 2.0;
        float layer1 = smoothstep(0.25, 0.75, rainAmount);
        float layer2 = smoothstep(0.0, 0.5, rainAmount);
        float3 c3 = Drops(uv, t, staticDrops, layer1, layer2);
        float2 c = c3.xy;
        float2 n = float2(0.0);
        if (amzp_refr > 0.0 && c3.z > 0.2) {
            float2 e = float2(0.001, 0.0);
            float cx = Drops(uv + e, t, staticDrops, layer1, layer2).x;
            float cy = Drops(uv + e.yx, t, staticDrops, layer1, layer2).x;
            n = float2(cx - c.x, cy - c.x) * amzp_refr;
        }
        if ((amzp_xnxx>0.5)) {
            n *= 1.0 - smoothstep(60.0, 85.0, T);
            c.y *= 1.0 - smoothstep(80.0, 100.0, T) * 0.8;
        }
        float focus = mix(maxBlur - c.y, minBlur, smoothstep(0.1, 0.2, c.x));
        float4 col = tex(UV + n);
        if (amzp_fog > 0.0) {
            float fz = clamp((focus - minBlur * (1.0 - amzp_fogClear)) / max(maxBlur, 0.001), 0.0, 1.0);
            fz = mix(1.0, fz, amzp_fogClear);
            float r = amzp_fog * fz;
            if (r > 0.3) {
                float nq = amzp_quality < 1.5 ? 4.0 : (amzp_quality < 2.5 ? 8.0 : (amzp_quality < 3.5 ? 12.0 : (amzp_quality < 4.5 ? 16.0 : 24.0)));
                float4 acc = col;
                for (int i = 0; i < 24; i++) {
                    float fi = float(i);
                    if (fi >= nq) break;
                    float rr = sqrt((fi + 0.5) / nq) * r;
                    float a = fi * 2.399963;
                    acc += tex(UV + n + float2(cos(a), sin(a)) * rr / screen.zw);
                }
                col = acc / (nq + 1.0);
            }
        }
        if ((amzp_xxx>0.5)) {
            float sp = clamp(dot(n / max(amzp_refr, 0.001), float2(-0.6, 0.8)) * 25.0, 0.0, 1.0);
            col.rgb += float3(sp * sp * 0.6) * col.a;
        }
        if ((amzp_lightfx>0.5)) {
            float tl = (T + 3.0) * 0.5;
            float colFade = sin(tl * 0.2) * amzp_aai + 0.5 + story;
            col.rgb *= mix(float3(1.0), float3(0.8, 0.9, 1.3), colFade);
            float fade = smoothstep(0.0, 10.0, T);
            float lightning = sin(tl * sin(tl * 10.0));
            lightning *= pow(max(0.0, sin(tl + sin(tl))), 10.0);
            col.rgb *= 1.0 + lightning * fade * mix(1.0, 0.1, story * story) * 0.5;
            float2 vv = UV - 0.5;
            col.rgb *= 1.0 - dot(vv, vv);
            if ((amzp_xnxx>0.5)) {
                col.rgb = mix(pow(max(col.rgb, 0.0), float3(1.2)), col.rgb, heart);
                fade *= smoothstep(102.0, 97.0, T);
            }
            col.rgb *= fade;
        }
        amzOutput = mix(texColor, col, amzp_alpha) * texColor.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
